   var observed=Clone(after);int native=Program.StrictInt(((IEnumerable)original["entityKey"]).Cast<object>().Last());var src=Obj(EntitySets.Inventory(before).Single(e=>Equals(e["nativeTypeCode"],59)&&Equals(e["nativeId"],native)),"geometry");var dst=Obj(EntitySets.Inventory(observed).Single(e=>Equals(e["nativeTypeCode"],59)&&Equals(e["nativeId"],native)),"geometry");foreach(string k in new[]{"min_rangeRaw","max_rangeRaw"}){var x=Numbers(src[k]);var y=Numbers(dst[k]);Need(x.Length==3&&y.Length==3&&Enumerable.Range(0,3).All(i=>Math.Abs(y[i]-(x[i]+delta[i]))<=0.000001),"Observed curve world range differs.");dst[k]=src[k];}Need(EntitySets.ObservedDigest(before)==EntitySets.ObservedDigest(observed),"Other curve/SOLID/context/units/properties changed.");
